mapper.select:
SELECT ar.id, ar.user_id, ut.username AS user_account, ut.name AS user_name, ar.type, ar.item_type, ar.item_type_str, COALESCE(it2.name, it.name, ar.item_type_str) AS item_type_name, ar.item_id, COALESCE(item.item_code, '') AS item_code, COALESCE(item.name, ar.item_name_temp) AS item_name, ar.item_name_temp, ar.quantity, ar.apply_time, ar.status, ar.reviewer_id, a.name AS admin_name, ar.review_time, ar.review_remark, ar.storage_id, s.name AS storage_name, ar.remark, ar.unit_price, ar.total_price, ar.purchase_dept, ar.purpose, ar.model AS model, ar.purchase_way, ar.model_temp FROM application_record ar LEFT JOIN usertable ut ON ar.user_id = ut.id LEFT JOIN item ON ar.item_id = item.id LEFT JOIN itemtype it ON ar.item_type = it.id LEFT JOIN itemtype it2 ON item.type_id = it2.id LEFT JOIN storage s ON ar.storage_id = s.id LEFT JOIN admin a ON ar.reviewer_id = a.id
AND type = #{type}
AND item_type = #{itemType}
AND item_name LIKE CONCAT('%', #{itemName}, '%')
AND storage_id = #{storageId}
AND user_id = #{userId}
AND ar.model LIKE CONCAT('%', #{model}, '%')
AND status IN
#{s}
ORDER BY CASE status WHEN 'pending' THEN 1 WHEN 'approved' THEN 2 WHEN 'rejected' THEN 3 WHEN 'completed' THEN 4 ELSE 5 END ASC, apply_time DESC

mapper.update:
update `application_record` set user_id = #{userId}, type = #{type}, item_type= #{itemType}, item_type_str = #{itemTypeStr}, item_name_temp = #{itemNameTemp}, item_id = #{itemId}, quantity= #{quantity}, apply_time = #{applyTime}, status = #{status}, reviewer_id = #{reviewerId}, review_time = #{reviewTime}, review_remark = #{reviewRemark}, storage_id = #{storageId}, remark = #{remark}, unit_price = #{unitPrice}, total_price = #{totalPrice}, purchase_dept = #{purchaseDept}, purpose = #{purpose}, model = #{model}, model_temp = #{modelTemp}, purchase_way = #{purchaseWay}
, name_id = #{nameId}
where id = #{id}
